      c.fillStyle = `rgba(150,140,130,${0.4 * (1 - p)})`;
      c.beginPath();
      c.arc(w * 0.66 + Math.sin(t * 2) * 0.8, h * 0.54 - 4.4 - p * 6, 0.6 + p * 1.2, 0, TAU163);
      c.fill();
      c.restore();
